1	//! SQLite runs the shared conformance suite (spec §5).
2	
3	use std::sync::Arc;
4	use std::time::Duration;
5	
6	use paigasus_helikon_core::Session;
7	use paigasus_helikon_sessions_sqlite::SqliteSession;
8	use paigasus_helikon_sessions_testkit::run_all;
9	use sqlx::sqlite::{SqliteConnectOptions, SqliteJournalMode, SqlitePoolOptions, SqliteSynchronous};
10	
11	#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
12	async fn sqlite_passes_conformance() {
13	    let dir = tempfile::tempdir().unwrap();
14	    let path = dir.path().join("conf.db");
15	    // Pool sizing rationale: see concurrent_writers.rs — the testkit's
16	    // run_concurrent_writers (via run_all) replays the same 16×10 workload
17	    // here (SMA-431).
18	    let opts = SqliteConnectOptions::new()
19	        .filename(&path)
20	        .create_if_missing(true)
21	        .journal_mode(SqliteJournalMode::Wal)
22	        .synchronous(SqliteSynchronous::Normal)
23	        .busy_timeout(Duration::from_secs(120));
24	    let pool = SqlitePoolOptions::new()
25	        .max_connections(8)
26	        .connect_with(opts)
27	        .await
28	        .unwrap();
29	    SqliteSession::migrate(&pool).await.unwrap();
30	
31	    // Unique session id per make() call -> fresh empty session each time.
32	    let counter = std::sync::atomic::AtomicU64::new(0);
33	    run_all(|| {
34	        let pool = pool.clone();
35	        let id = counter.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
36	        async move {
37	            Arc::new(SqliteSession::open_without_migrate(
38	                pool,
39	                format!("conf-{id}"),
40	            )) as Arc<dyn Session>
41	        }
42	    })
43	    .await;
44	    // keep `dir` alive until here
45	    drop(dir);
46	}
47

1	//! Postgres conformance — runs only when HELIKON_TEST_POSTGRES_URL is set
2	//! (loud-skips otherwise, like forkd_live). spec §9.
3	
4	use std::sync::atomic::{AtomicU64, Ordering};
5	use std::sync::Arc;
6	
7	use paigasus_helikon_core::Session;
8	use paigasus_helikon_sessions_postgres::PostgresSession;
9	use paigasus_helikon_sessions_testkit::run_all;
10	
11	#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
12	async fn postgres_passes_conformance() {
13	    let Ok(url) = std::env::var("HELIKON_TEST_POSTGRES_URL") else {
14	        eprintln!("SKIP postgres_passes_conformance: HELIKON_TEST_POSTGRES_URL unset");
15	        return;
16	    };
17	    let pool = sqlx::PgPool::connect(&url).await.expect("connect");
18	    PostgresSession::migrate(&pool).await.expect("migrate"); // migrate ONCE up front
19	
20	    // Process-unique prefix so reruns against a reused database never collide
21	    // with a prior run's rows for the same session id.
22	    let pid = std::process::id();
23	    let counter = AtomicU64::new(0);
24	    run_all(|| {
25	        let pool = pool.clone();
26	        let id = counter.fetch_add(1, Ordering::SeqCst);
27	        async move {
28	            Arc::new(PostgresSession::open_without_migrate(
29	                pool,
30	                format!("conf-{pid}-{id}"),
31	            )) as Arc<dyn Session>
32	        }
33	    })
34	    .await;
35	}
